-- Uploaded files (videos, PDFs, images) and the course/lesson links to them.
-- Tables: file_upld_dtl_t
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public.file_upld_dtl_t (
    file_id text NOT NULL,
    college_id text NOT NULL,
    storage_key_tx text NOT NULL,
    orgnl_file_nm text NOT NULL,
    mime_type_tx text NOT NULL,
    size_bytes_ct integer NOT NULL,
    checksum_tx text NOT NULL,
    purpose_cd public."FilePurpose" NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    lesson_id text,
    CONSTRAINT file_upld_dtl_t_a_in_check CHECK ((a_in = ANY (ARRAY[0, 1]))),
    CONSTRAINT file_upld_dtl_t_size_bytes_ct_check CHECK ((size_bytes_ct >= 0))
);

ALTER TABLE ONLY public.file_upld_dtl_t
    ADD CONSTRAINT file_upld_dtl_t_pkey PRIMARY KEY (file_id);

CREATE INDEX file_upld_dtl_t_college_id_idx ON public.file_upld_dtl_t USING btree (college_id);

CREATE INDEX file_upld_dtl_t_lesson_id_idx ON public.file_upld_dtl_t USING btree (lesson_id) WHERE (lesson_id IS NOT NULL);

CREATE UNIQUE INDEX file_upld_dtl_t_storage_key_tx_key ON public.file_upld_dtl_t USING btree (storage_key_tx);

CREATE TRIGGER file_upld_dtl_t_audit_timestamps BEFORE UPDATE ON public.file_upld_dtl_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

-- Foreign keys
ALTER TABLE ONLY public."Course"
    ADD CONSTRAINT "Course_syllabus_file_id_fkey" FOREIGN KEY (syllabus_file_id) REFERENCES public.file_upld_dtl_t(file_id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE ONLY public."Lesson"
    ADD CONSTRAINT "Lesson_file_id_fkey" FOREIGN KEY (file_id) REFERENCES public.file_upld_dtl_t(file_id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE ONLY public.file_upld_dtl_t
    ADD CONSTRAINT file_upld_dtl_t_college_id_fkey FOREIGN KEY (college_id) REFERENCES public."College"(id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE ONLY public.file_upld_dtl_t
    ADD CONSTRAINT file_upld_dtl_t_lesson_id_fkey FOREIGN KEY (lesson_id) REFERENCES public."Lesson"(id) ON UPDATE CASCADE ON DELETE SET NULL;

COMMIT;
